local config = {
  ui_story_5048_50480101_1_dialog_content = "<color=#e8d9bb>Chirrido, chirrido, chirrido...</color>",
  ui_story_5048_50480101_2_dialog_content = "<color=#e8d9bb>Twin Pavilions Bay - Distrito Oeste</color>",
  ui_story_5048_50480101_3_dialog_content = "¿Su Alteza?",
  ui_story_5048_50480101_4_dialog_content = "<size=50>¡Princesa Dantang!</size>",
  ui_story_5048_50480101_5_dialog_content = "¿Mmm?",
  ui_story_5048_50480101_6_dialog_content = "Sus ojos estaban cerrados tan fuertemente, Su Alteza, y estaba tan silencioso... Por favor, dígame, ¿siente algún tipo de malestar?",
  ui_story_5048_50480101_7_dialog_content = "Lo siento por preocuparte, Jiu, solo estaba concentrado en esta maravillosa y dulce pieza de piano.",
  ui_story_5048_50480101_8_dialog_content = "Escucha: es tan suave como el agua, pero también posee una elegancia grandiosa. Es completamente diferente de los instrumentos de Longzhou. Qué deleite para los oídos.",
  ui_story_5048_50480101_9_dialog_content = "Si tengo la oportunidad en el futuro, me encantaría tocar junto a un pianista y tal vez tú puedas realizar un baile de espadas a mi lado...",
  ui_story_5048_50480101_10_dialog_content = "Eres un verdadero visionario, Su Alteza.",
  ui_story_5048_50480101_11_dialog_content = "¿No te parece extraño? Dicen que <color=#FFB400>Twin Pavilions Bay</color> disfruta de abundantes lluvias y un clima agradable durante esta temporada... Sin embargo, últimamente ha estado tan caliente y seco.",
  ui_story_5048_50480101_12_dialog_content = "¿Es tu primera vez en Twin Pavilions Bay?",
  ui_story_5048_50480101_13_dialog_content = "El clima ha sido un poco inusual en Twin Pavilions Bay este año. Todos esperamos una fresca brisa marina y una buena lluvia.",
  ui_story_5048_50480101_14_dialog_content = "Vaya, lo siento, me desvié un poco del tema. Aquí está tu pedido, todos los platos que ordenaste.",
  ui_story_5048_50480101_15_dialog_content = "Esperamos que el hermoso paisaje pueda disipar cualquier incomodidad causada por el clima caluroso. Disfruten de su comida.",
  ui_story_5048_50480101_16_dialog_content = "Como era de esperar del restaurante más famoso de Twin Pavilions Bay, el servicio aquí es realmente excepcional.",
  ui_story_5048_50480101_17_dialog_content = "Su Alteza, hay algo que aún no entiendo del todo.",
  ui_story_5048_50480101_18_dialog_content = "La pequeña Longzhou en el este de la ciudad alberga muchos restaurantes que sirven los platos al estilo de Longzhou a los que estás tan acostumbrado.",
  ui_story_5048_50480101_19_dialog_content = "Entonces, ¿por qué insistes en visitar este restaurante Astra en el oeste de la ciudad cuando te da hambre?",
  ui_story_5048_50480101_20_dialog_content = "El primer paso de la diplomacia es comprender las costumbres y tradiciones locales, y el primer paso para adquirir tal comprensión es...",
  ui_story_5048_50480101_21_dialog_content = "Bueno, naturalmente, comenzar con la comida local es la forma más rápida.",
  ui_story_5048_50480101_22_dialog_content = "Tiene toda la razón, Su Alteza.",
  ui_story_5048_50480101_23_dialog_content = "¿Mmm? Perdona mi negligencia, debería haber pedido palillos para nuestra mesa. Llamaré al camarero.",
  ui_story_5048_50480101_24_dialog_content = "Mira, Jiu, estos cuchillos y tenedores son los cubiertos aquí.",
  ui_story_5048_50480101_25_dialog_content = "Cuchillos y tenedores... ¿como cubiertos? ¿Por qué me parecen más como armas personales?",
  ui_story_5048_50480101_26_dialog_content = "Jaja. Sé que tienes que practicar tus artes marciales todo el día, pero realmente necesitas leer algunos de los libros que te di cuando tengas tiempo. Aprende algo sobre la cultura aquí.",
  ui_story_5048_50480101_27_dialog_content = "Si...",
  ui_story_5048_50480101_28_dialog_content = "Bueno, si los cubiertos están listos, ¿por qué no está comiendo, Su Alteza?",
  ui_story_5048_50480101_29_dialog_content = "Solo me preguntaba cómo ibas a comer con esa máscara puesta.",
  ui_story_5048_50480101_30_dialog_content = "Su Alteza, por supuesto, le serviré mientras cena.",
  ui_story_5048_50480101_31_dialog_content = "¿Todavía no te acostumbras a mostrar tu cara en público?",
  ui_story_5048_50480101_32_dialog_content = "Temo que mi apariencia pueda ofender los ojos de Su Alteza, impidiendo que Su Alteza pueda comer...",
  ui_story_5048_50480101_33_dialog_content = "Está bien, pero ¿no te he dicho que ni siquiera la palabra \"hermosa\" hace justicia a tu apariencia? ¿Por qué todavía no me crees?",
  ui_story_5048_50480101_34_dialog_content = "Oh, ¿debo comer toda esta deliciosa comida solo? ¿Estás tan ansioso por verme sufrir de indigestión?",
  ui_story_5048_50480101_35_dialog_content = "¡Nunca soñaría con algo así!",
  ui_story_5048_50480101_36_dialog_content = "Ahem... Vamos, inténtalo.",
  ui_story_5048_50480101_37_dialog_content = "¡Sí, Su Alteza!",
  ui_story_5048_50480101_38_dialog_content = "<color=#e8d9bb>Jiu probó cuidadosamente todos los platos.</color>",
  ui_story_5048_50480101_39_dialog_content = "¿Qué piensas?",
  ui_story_5048_50480101_40_dialog_content = "Su Alteza, he probado todo y puede estar seguro de que la comida no está envenenada.",
  ui_story_5048_50480101_41_dialog_content = "Quiero saber qué opinas del sabor. ¿Es de tu agrado?",
  ui_story_5048_50480101_42_dialog_content = "Eso... No estaba prestando atención.",
  ui_story_5048_50480101_43_dialog_content = "La próxima vez, saborea cada bocado cuidadosamente conmigo. Asegúrate de no desperdiciar estas delicias raras de nuevo.",
  ui_story_5048_50480101_44_dialog_content = "Ya veo. Su Alteza no tenía la intención de que yo probara la comida en busca de veneno...",
  ui_story_5048_50480101_45_dialog_content = "Por supuesto. ¿De qué otra manera podrás disfrutar de esta deliciosa comida conmigo?",
  ui_story_5048_50480101_46_dialog_content = "Su Alteza, le pido que espere un momento!",
  ui_story_5048_50480101_47_dialog_content = "Al observar más de cerca justo ahora, me di cuenta de algo...",
  ui_story_5048_50480101_48_dialog_content = "El relleno de esta pizza de horno de piedra en realidad no se ha horneado en la masa...",
  ui_story_5048_50480101_49_dialog_content = "¡Este Beef Roayl no se ha cocinado correctamente! ¡Solo mira todas las vetas de sangre que lo atraviesan!",
  ui_story_5048_50480101_50_dialog_content = "¡Y esta Ensalada Estacional con Miel claramente contiene vegetales crudos! ¡No han sido cocinados en absoluto!",
  ui_story_5048_50480101_51_dialog_content = "¿Realmente se pueden llamar delicias de Twin Pavilions Bay a platos elaborados tan descuidadamente?",
  ui_story_5048_50480101_52_dialog_content = "Cálmate, Jiu—no seas impaciente. Como dice el dicho, el entorno juega un papel importante en el desarrollo de uno.",
  ui_story_5048_50480101_53_dialog_content = "Tengan en cuenta que existen diferencias regionales en la dieta entre los diversos reinos vasallos de Longzhou, y estas diferencias son aún más notables en Astra, ya que está separado de nosotros por un vasto océano.",
  ui_story_5048_50480101_54_dialog_content = "Aprender a apreciar las cocinas de diferentes regiones es otra de las lecciones que debemos aprender en nuestro viaje por el mundo.",
  ui_story_5048_50480101_55_dialog_content = "Esta pizza de horno de piedra no es una de nuestras tartas de Longzhou.",
  ui_story_5048_50480101_56_dialog_content = "Esta pizza ha sido horneada especialmente en un horno de piedra de alta temperatura y, idealmente, debe tener una corteza crujiente, un relleno abundante y queso fresco y fragante.",
  ui_story_5048_50480101_57_dialog_content = "¿Qué tal este Bistec Real?",
  ui_story_5048_50480101_58_dialog_content = "En Longzhou, solemos saltear nuestra carne hasta que esté suave y tierna, y la condimentamos con diferentes sazones.",
  ui_story_5048_50480101_59_dialog_content = "Sin embargo, este Beef Royal busca preservar el sabor original de los ingredientes en la mayor medida posible. La carne es fresca, tierna y jugosa, y se deshace en la boca...",
  ui_story_5048_50480101_60_dialog_content = "Si la calidad de la carne no hubiera sido controlada estrictamente desde la etapa de cría, habría sido imposible producir ese sabor.",
  ui_story_5048_50480101_61_dialog_content = "Dicen que en el pasado, solo el prestigioso Noble de Lumo tenía permitido degustar este platillo.",
  ui_story_5048_50480101_62_dialog_content = "Ya veo... ¿Cuál es la historia detrás de esta Ensalada Estacional con Miel?",
  ui_story_5048_50480101_63_dialog_content = "Estas verduras son realmente muy frescas y están presentes en gran variedad. De hecho, muchas de ellas no se cultivan localmente.",
  ui_story_5048_50480101_64_dialog_content = "Un restaurante que puede proporcionar verduras frescas a los comensales de otros lugares en este calor sofocante...",
  ui_story_5048_50480101_65_dialog_content = "Ya sea manteniendo la buena fe o almacenando y conservando alimentos, todo lo que hacen es de primera clase.",
  ui_story_5048_50480101_66_dialog_content = "El único problema es que este aderezo es un poco demasiado dulce para mi gusto. Si tan solo los clientes pudieran elegir sus propias salsas.",
  ui_story_5048_50480101_67_dialog_content = "Su Alteza, aunque recientemente se ha familiarizado con las delicias de Astra, ya ha desarrollado un entendimiento tan profundo de ellas... ¡Usted es, sin duda, la joya de la corona del Reino Ye!",
  ui_story_5048_50480101_68_dialog_content = "Jiu, ¿por qué me has estado halagando tanto estos días?",
  ui_story_5048_50480101_69_dialog_content = "¿Podría ser que aprendiste algunos trucos de algún <color=#FFB400>hablador persuasivo</color> a bordo del barco en nuestro camino aquí?",
  ui_story_5048_50480101_70_dialog_content = "Si a Su Alteza no le gusta, hablaré menos.",
  ui_story_5048_50480101_71_dialog_content = "Jiu, realmente necesitas aprender a reconocer y reaccionar ante las bromas juguetonas...",
  ui_story_5048_50480101_72_dialog_content = "¿Mmm?",
  ui_story_5048_50480101_73_dialog_content = "¡¿Qué crees que estás haciendo?!",
  ui_story_5048_50480101_74_dialog_content = "Ah...",
  ui_story_5048_50480101_75_dialog_content = "Los estás asustando.",
  ui_story_5048_50480101_76_dialog_content = "Perdona mi grosería.",
  ui_story_5048_50480101_77_dialog_content = "Pero interrumpiste a los dos en medio de nuestra comida. ¿Cuál es el problema?",
  ui_story_5048_50480101_78_dialog_content = "Eh, aquí está la cosa.",
  ui_story_5048_50480101_79_dialog_content = "Nuestro jefe, el Sr. Ernest, acaba de escuchar sus comentarios sobre nuestros platos y se llevó una grata sorpresa.",
  ui_story_5048_50480101_80_dialog_content = "\"Tener percepciones tan acertadas de nuestra cocina local en tu primer intento es realmente notable.\"",
  ui_story_5048_50480101_81_dialog_content = "Nuestro jefe quiere invitarlos a ambos a nuestra cocina y discutir el arte de cocinar si tienen tiempo para ello.",
  ui_story_5048_50480101_82_dialog_content = "¿Considerarían ambos honrarnos con su presencia?",
  ui_story_5048_50480101_83_dialog_content = "Eres muy amable, simplemente di algunas opiniones francas que quizás no sean convencionales antes.",
  ui_story_5048_50480101_84_dialog_content = "Es muy generoso por parte del propietario invitarnos, y su amplitud de miras es realmente admirable. Estaremos más que felices de aceptar su invitación.",
  ui_story_5048_50480101_85_dialog_content = "¡Su Alteza! Somos nuevos aquí y aún no estamos familiarizados con las costumbres locales.",
  ui_story_5048_50480101_86_dialog_content = "Si aceptamos imprudentemente una invitación de un extraño y desaparecemos de la vista pública, podría...",
  ui_story_5048_50480101_87_dialog_content = "Si me conoces en absoluto, deberías saber que no soy precisamente una debilucha sin fuerzas para defenderse.",
  ui_story_5048_50480101_88_dialog_content = "Además, ¿no estoy acompañado por un guardaespaldas con habilidades de artes marciales sin igual?",
  ui_story_5048_50480101_89_dialog_content = "Por supuesto, estaré aquí naturalmente para protegerte.",
  ui_story_5048_50480101_90_dialog_content = "Aunque aún no hemos tenido la oportunidad de hablar sobre el arte del piano con el pianista... discutir manjares con un gourmet primero también es una maravillosa oportunidad.",
  ui_story_5048_50480101_91_dialog_content = "Y así, te pido que guíes el camino, si te agrada.",
  ui_story_5048_50480101_92_dialog_content = "Estimados invitados, por favor, vengan por aquí.",
  ui_story_5048_50480101_93_dialog_content = "<color=#e8d9bb>¡Una serie de tintineos y estrépitos!</color>",
  ui_story_5048_50480101_94_dialog_content = "Oh no, ¿es posible que alguien haya dejado caer los platos mientras servía? El jefe se va a enojar otra vez...",
  ui_story_5048_50480101_95_dialog_content = "N-Necesito ayuda por aquí!",
  ui_story_5048_50480101_96_dialog_content = "¡Ayuda!",
  ui_story_5048_50480101_97_dialog_content = "¿Eh? Es eso...",
  ui_story_5048_50480101_98_dialog_content = "¿Li Tianxian?!",
  ui_story_5048_50480201_1_dialog_content = "<color=#e8d9bb>Hace un tiempo</color>",
  ui_story_5048_50480201_2_dialog_content = "<color=#e8d9bb>Chirrido, chirrido, chirrido...</color>",
  ui_story_5048_50480201_3_dialog_content = "El melón dorado se arrugó.",
  ui_story_5048_50480201_4_dialog_content = "Fecha de hundimiento de plata.",
  ui_story_5048_50480201_5_dialog_content = "El estómago vacío ruge.",
  ui_story_5048_50480201_6_dialog_content = "¡El bolsillo del pobre hace clank!",
  ui_story_5048_50480201_7_dialog_content = "... Squawk, Jabber, ¿pueden los dos calmarse un momento?",
  ui_story_5048_50480201_8_dialog_content = "¡Vacaciones! ¡Vacaciones!",
  ui_story_5048_50480201_9_dialog_content = "¡Vete a casa! ¡Vete a casa!",
  ui_story_5048_50480201_10_dialog_content = "Si el negocio no mejora pronto, ¿de dónde sacaremos el dinero para los melones dorados y los dátiles plateados?",
  ui_story_5048_50480201_11_dialog_content = "Pero no te preocupes. Recorro el mundo, vagando por aquí y por allá. ¿Cuándo los he dejado a ustedes dos pasar hambre?",
  ui_story_5048_50480201_12_dialog_content = "Espera un poco más...",
  ui_story_5048_50480201_13_dialog_content = "¿Mmm?",
  ui_story_5048_50480201_14_dialog_content = "Solo mira, ¿no está cerca nuestro cambio de destino?",
  ui_story_5048_50480201_15_dialog_content = "¡Bienvenido! Señor, ¿va a cenar solo?",
  ui_story_5048_50480201_16_dialog_content = "Estoy buscando a alguien.",
  ui_story_5048_50480201_17_dialog_content = "Está adentro, puedo encontrarlo yo mismo, ¡no hay necesidad de que te molestes!",
  ui_story_5048_50480201_18_dialog_content = "De acuerdo, señor.",
  ui_story_5048_50480201_19_dialog_content = "Increíble... Es tan espacioso y luminoso aquí, y mucho más fresco que afuera. Qué maravillosa joya he encontrado.",
  ui_story_5048_50480201_20_dialog_content = "Ahora, es hora de buscar. Veamos...",
  ui_story_5048_50480201_21_dialog_content = "¡Vaya, piedra a los cuervos!",
  ui_story_5048_50480201_22_dialog_content = "Es evidente que eres una persona de gran riqueza y estatura, pero ¿qué ha hecho que tus cejas se frunzan y tu rostro se llene de tristeza hoy?",
  ui_story_5048_50480201_23_dialog_content = "Algo te preocupa.",
  ui_story_5048_50480201_24_dialog_content = "Sea lo que sea, no creo que tenga algo que ver contigo.",
  ui_story_5048_50480201_25_dialog_content = "¿En serio? Pero, ¿cómo es que no tiene nada que ver conmigo?",
  ui_story_5048_50480201_26_dialog_content = "Permítanme presentarme. Soy Li Tianxian, recién llegado del ferry de Longzhou.",
  ui_story_5048_50480201_27_dialog_content = "Aunque no puedo hablar de mis propias habilidades, algunos me consideran algo así como un gran artesano.",
  ui_story_5048_50480201_28_dialog_content = "¿Un artesano, eh? ¿No serás un chef, por casualidad?",
  ui_story_5048_50480201_29_dialog_content = "No, no, no. Verás, la vida y la muerte están dictadas por el destino, la riqueza y el prestigio por los cielos. Soy un maestro del principio del Yin y Yang y la teoría de los Cinco Elementos, con una tasa mínima de precisión en las predicciones garantizada del noventa por ciento.",
  ui_story_5048_50480201_30_dialog_content = "Mi habilidad se conoce como <color=#FFB400>adivinación</color>.",
  ui_story_5048_50480201_31_dialog_content = "Puedo trazar el curso de tu destino, guiarte de manera segura más allá de las trampas del destino y, a veces... incluso cambiar el futuro, desafiando a los mismísimos cielos.",
  ui_story_5048_50480201_32_dialog_content = "Cualquier dificultad que enfrentes, ponla en mis manos y te proporcionaré una solución.",
  ui_story_5048_50480201_33_dialog_content = "¡Satisfacción garantizada!",
  ui_story_5048_50480201_34_dialog_content = "¡Precisión total, o te devolvemos tu dinero!",
  ui_story_5048_50480201_35_dialog_content = "Señor, si no está aquí para cenar, por favor evite molestar a nuestros estimados invitados y retírese ahora.",
  ui_story_5048_50480201_36_dialog_content = "Ahora, ahora, ahora... Hay un momento y un lugar para todo, y en este momento, aún no he terminado de hablar con su distinguido invitado.",
  ui_story_5048_50480201_37_dialog_content = "¿Al menos lo pensarás?",
  ui_story_5048_50480201_38_dialog_content = "Si no estás satisfecho, me marcho.",
  ui_story_5048_50480201_39_dialog_content = "Deja que él tome asiento.",
  ui_story_5048_50480201_40_dialog_content = "Sr. Víctor...?",
  ui_story_5048_50480201_41_dialog_content = "No te preocupes por eso, adelante y vuelve a tus deberes.",
  ui_story_5048_50480201_42_dialog_content = "Jejeje, amigo mío, deberías intentar ser más respetuoso con tus clientes en el futuro.",
  ui_story_5048_50480201_43_dialog_content = "...",
  ui_story_5048_50480201_44_dialog_content = "Sr. Victor, parece que todos los que trabajan aquí te conocen. Debes ser un cliente habitual.",
  ui_story_5048_50480201_45_dialog_content = "Sí, podrías decir eso.",
  ui_story_5048_50480201_46_dialog_content = "¡Gracias por tu amable ayuda hace un momento!",
  ui_story_5048_50480201_47_dialog_content = "Encontrar un alma tan amable y justa como la tuya es un acontecimiento raro en estos días. Por lo tanto, te concederé una adivinación a precio de descuento.",
  ui_story_5048_50480201_48_dialog_content = "Si tus poderes realmente son tan impresionantes como dices, no te trataré injustamente.",
  ui_story_5048_50480201_49_dialog_content = "Ahora, déjame ver qué puedes hacer.",
  ui_story_5048_50480201_50_dialog_content = "<color=#e8d9bb>¡¡Whoooosh!!</color>",
  ui_story_5048_50480201_51_dialog_content = "Rata Yin arriba, Buey Yang abajo.",
  ui_story_5048_50480201_52_dialog_content = "Buen señor, la adivinación muestra una rata montando en la espalda de un buey.",
  ui_story_5048_50480201_53_dialog_content = "La alternancia de yin y yang, el conflicto universal: toda discordia está interconectada con causa y efecto.",
  ui_story_5048_50480201_54_dialog_content = "La imagen mostrada en este hexagrama revela tu futura estrategia para superar este conflicto.",
  ui_story_5048_50480201_55_dialog_content = "¿Mmm? Escuchémoslo entonces.",
  ui_story_5048_50480201_56_dialog_content = "En primer lugar, si no quieres convertirte en un escalón para el éxito de los demás, debes tomar precauciones adicionales contra aquellos que quieran hacerte daño.",
  ui_story_5048_50480201_57_dialog_content = "¿Cómo puedo saber quién está intentando acabar conmigo?",
  ui_story_5048_50480201_58_dialog_content = "No se preocupe, señor, porque esta adivinación tiene un segundo significado.",
  ui_story_5048_50480201_59_dialog_content = "Aunque te encuentres con personas de naturaleza despreciable, siempre recibirás la ayuda de los virtuosos en momentos de peligro, encontrando un nuevo camino a seguir y convirtiendo las desgracias en bendiciones.",
  ui_story_5048_50480201_60_dialog_content = "¿Virtuosos, dices?",
  ui_story_5048_50480201_61_dialog_content = "Es decir, en el último momento, alguien vendrá a tu rescate y todos tus problemas se resolverán fácilmente.",
  ui_story_5048_50480201_62_dialog_content = "Y siempre estarás bendecido con buena suerte, durante toda tu vida.",
  ui_story_5048_50480201_63_dialog_content = "¡Jajaja! ¡Excelente! Con gusto pagaré por esas palabras auspiciosas. Espero que realmente tenga buena suerte, tal como dijiste.",
  ui_story_5048_50480201_64_dialog_content = "Oh, realmente eres un alma bondadosa... Mi noble benefactor, por favor acepta mi más profunda gratitud y una reverencia aún más profunda de tu humilde servidor.",
  ui_story_5048_50480201_65_dialog_content = "¡Hmph! ¿Te consideras un artesano solo porque sabes decirle a la gente lo que quiere escuchar?",
  ui_story_5048_50480201_66_dialog_content = "Y el hecho de que estés haciendo todo esto por unas monedas te hace aún más despreciable.",
  ui_story_5048_50480201_67_dialog_content = "...",
  ui_story_5048_50480201_68_dialog_content = "Señor, no le guardo rencor. ¿Por qué razón siente la necesidad de reprenderme tan duramente?",
  ui_story_5048_50480201_69_dialog_content = "Esas palabras no me afectan personalmente, pero si afectan tu estado de ánimo, seguramente tus pérdidas superan tus ganancias.",
  ui_story_5048_50480201_70_dialog_content = "¿La comida de hoy es de su agrado?",
  ui_story_5048_50480201_71_dialog_content = "(Sus palabras son duras, pero parece que no lo hace por mal...)",
  ui_story_5048_50480201_72_dialog_content = "Sí, es delicioso.",
  ui_story_5048_50480201_73_dialog_content = "¿Cómo sabrías a qué sabe si ni siquiera has probado un bocado?",
  ui_story_5048_50480201_74_dialog_content = "¿Es esto lo que realmente quieres de la vida? ¿Fingir que todo está bien y perseguir una apariencia superficial de paz?",
  ui_story_5048_50480201_75_dialog_content = "Eres un gourmet. Descartar cualquier plato que se te presente como delicioso es el principio del fin para un hombre con estándares.",
  ui_story_5048_50480201_76_dialog_content = "Hay más de un conjunto de estándares en este mundo, y tengo mi propia forma de ver las cosas.",
  ui_story_5048_50480201_77_dialog_content = "Señalar simplemente las desagradables verdades del mundo no es suficiente para sobrevivir en él. Si no podemos lograr ni siquiera una paz superficial, ¿qué esperanza tenemos de alcanzar una paz verdadera?!",
  ui_story_5048_50480201_78_dialog_content = "(Tch... Me temo que otro misterio puede estar detrás del enfrentamiento entre estos dos.)",
  ui_story_5048_50480201_79_dialog_content = "Amigo mío, por favor, no te alteres así. ¿Recuerdas la adivinación de hace un momento?",
  ui_story_5048_50480201_80_dialog_content = "Este tipo de angustia emocional seguramente avivará tu fuego interior, lo que podría llevar fácilmente a un rápido deterioro de tu salud. Si tu némesis ataca mientras estás en este estado, tu salvador no estará en ninguna parte y la tragedia seguirá.",
  ui_story_5048_50480201_81_dialog_content = "Eso realmente tiene sentido, Maestro Li.",
  ui_story_5048_50480201_82_dialog_content = "Creo que has estado escuchando demasiado las tonterías de este charlatán!",
  ui_story_5048_50480201_83_dialog_content = "Oh, por el amor de Dios, señor. La desgracia sale de la boca. Ten cuidado, no sea que te hagan tragarte esas palabras.",
  ui_story_5048_50480201_84_dialog_content = "¿Mmm? Señor, el color del espacio entre sus ojos está apagado. Esto podría ser una señal ominosa...",
  ui_story_5048_50480201_85_dialog_content = "¿Qué tal esto? Te daré una adivinación gratis y olvidaremos lo que pasó aquí hoy. ¿Qué te parece?",
  ui_story_5048_50480201_86_dialog_content = "¡No te creo ni un segundo!",
  ui_story_5048_50480201_87_dialog_content = "<color=#e8d9bb>¡¡¡Whoosh!!!</color>",
  ui_story_5048_50480201_88_dialog_content = "Hmm? Parece que has sacado accidentalmente dos papeles para formar una adivinación. Esto es...",
  ui_story_5048_50480201_89_dialog_content = "¿Caballo Yin y Buey Yin?!",
  ui_story_5048_50480201_90_dialog_content = "Un buey muerto tira de un caballo de madera, ninguno puede avanzar. Señor, ¡debes tener mucho cuidado!",
  ui_story_5048_50480201_91_dialog_content = "El desastre puede ocurrir en cualquier momento. ¡Debes eliminar todas las amenazas potenciales de inmediato y mantener la calma!",
  ui_story_5048_50480201_92_dialog_content = "Emm...",
  ui_story_5048_50480201_93_dialog_content = "¿Ernesto?",
  ui_story_5048_50480201_94_dialog_content = "Urgh...",
  ui_story_5048_50480201_95_dialog_content = "¿Qué te pasa? Si tienes algo que decir, simplemente dilo...",
  ui_story_5048_50480201_96_dialog_content = "Todo esto está dando frutos bastante rápido...",
  ui_story_5048_50480201_97_dialog_content = "Urrrgh...",
  ui_story_5048_50480201_98_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5048_50480201_99_dialog_content = "<color=#e8d9bb>¡Una serie de tintineos y estrépitos!</color>",
  ui_story_5048_50480201_100_dialog_content = "N-Necesito ayuda por aquí!",
  ui_story_5048_50480201_101_dialog_content = "¡Ayuda!",
  ui_story_5048_50480201_102_dialog_content = "¡Desastre golpea! ¡Salva su vida!",
  ui_story_5048_50480201_103_dialog_content = "¡Ayuda! ¡Alguien, ayuda!",
  ui_story_5048_50480201_104_dialog_content = "Tianxian, ¿qué estás haciendo aquí?",
  ui_story_5048_50480201_105_dialog_content = "Señorita Jiu? Princesa Dantang? Realmente no hay historia sin coincidencias, ni encuentro sin predestinación...",
  ui_story_5048_50480201_106_dialog_content = "¡¿Jefe?!",
  ui_story_5048_50480201_107_dialog_content = "Jefe, ¿qué te ha pasado? Vamos, despierta...",
  ui_story_5048_50480201_108_dialog_content = "Tez pálida, espuma en la boca... ¿Frente enrojecida como llamas?",
  ui_story_5048_50480201_109_dialog_content = "Estos síntomas... ¿No es esto envenenamiento por <color=#FFB400>llama de cuervo</color>?",
  ui_story_5048_50480201_110_dialog_content = "Ravenflame es un analgésico con propiedades calentadoras, ¡pero solo se puede aplicar tópicamente, no se puede tomar por vía oral!",
  ui_story_5048_50480201_111_dialog_content = "De lo contrario... Bueno, los casos leves de envenenamiento por ravenflame implican vómitos, diarrea y entumecimiento en todo el cuerpo, mientras que los casos graves se caracterizan por dificultad para respirar, convulsiones, delirio y paro cardíaco.",
  ui_story_5048_50480201_112_dialog_content = "Tal despiadada traición...",
  ui_story_5048_50480201_113_dialog_content = "Jiu, presiona su punto de acupuntura fuquan y oblígalo a escupir el veneno primero!",
  ui_story_5048_50480201_114_dialog_content = "¡Si su Alteza!",
  ui_story_5048_50480201_115_dialog_content = "¿Dónde está el médico más cercano? ¿Alguien puede guiarme?",
  ui_story_5048_50480201_116_dialog_content = "¡Lo sé! ¡Por aquí!",
  ui_story_5048_50480201_117_dialog_content = "¡Graagh!",
  ui_story_5048_50480201_118_dialog_content = "¡¿Qué?!",
  ui_story_5048_50480201_119_dialog_content = "¡Muévete!",
  ui_story_5048_50480201_120_dialog_content = "¡¿Cómo entraron los Eclipsites en Twin Pavilions Bay?!",
  ui_story_5048_50480201_121_dialog_content = "Lleva a Ernest al médico primero. Nosotros te cubrimos.",
  ui_story_5048_50480201_122_dialog_content = "Recuerda decirle al doctor que Ernest ha sido envenenado con ravenflame.",
  ui_story_5048_50480201_123_dialog_content = "¡O-bien, lo haré!",
  ui_story_5048_50480201_124_dialog_content = "Su Alteza, por favor tenga cuidado. ¡No se esfuerce demasiado!",
  ui_story_5048_50480201_125_dialog_content = "Jiu, quizás ha pasado mucho tiempo desde la última vez que me viste enfrentarme a un Eclipsite.",
  ui_story_5048_50480302_1_dialog_content = "Su Alteza, todos los Eclipsites han sido eliminados. No queda ni uno solo.",
  ui_story_5048_50480302_2_dialog_content = "Escuché que no hay Eclipsites desenfrenados en Twin Pavilions Bay, entonces, ¿cómo ocurrió exactamente la situación actual?",
  ui_story_5048_50480302_3_dialog_content = "Es bastante extraño.",
  ui_story_5048_50480302_4_dialog_content = "Volvamos al restaurante y echemos un vistazo.",
  ui_story_5048_50480302_5_dialog_content = "¡Definitivamente eres tú! Además de ti, ¿quién más podría ser el asesino?",
  ui_story_5048_50480302_6_dialog_content = "Mis queridos compatriotas, les aconsejo no lanzar tales insinuaciones tan a la ligera, ¡podría ser perjudicial para su fortuna!",
  ui_story_5048_50480302_7_dialog_content = "¡Todos lo escuchamos! ¡Eres tú quien usó palabras crueles para atacar al Sr. Ernesto!",
  ui_story_5048_50480302_8_dialog_content = "¡El Sr. Ernesto se desmayó justo después de que terminaste de hablar!",
  ui_story_5048_50480302_9_dialog_content = "Oh, el cielo lo sabe, causar daño a otros solo traería consecuencias negativas a mi propia vida. Nunca haría algo así.",
  ui_story_5048_50480302_10_dialog_content = "Entonces, ¿cómo sabes que esto es un asesinato premeditado?",
  ui_story_5048_50480302_11_dialog_content = "¡Definitivamente eres tú! ¡Tú eres el asesino!",
  ui_story_5048_50480302_12_dialog_content = "Se me viene a la mente un cierto sentimiento expresado por tales mercenarios: vivir por la espada, morir por la espada.",
  ui_story_5048_50480302_13_dialog_content = "Ha vivido su vida engañando a otros, oscureciendo la verdad... Ahora, la verdad no puede salvarlo.",
  ui_story_5048_50480302_14_dialog_content = "Su Alteza, Tianxian ciertamente tiene una lengua resbaladiza, pero no es una persona de naturaleza malvada.",
  ui_story_5048_50480302_15_dialog_content = "Si realmente ha sido acusado injustamente, también merece lástima.",
  ui_story_5048_50480302_16_dialog_content = "Tienes razón, no deberíamos verlo caer y ni siquiera mover un dedo para ayudar solo por sus engaños pasados.",
  ui_story_5048_50480302_17_dialog_content = "Además, no fue fácil para nosotros viajar tan lejos a bordo del Shadowind. Si alguno de nosotros fuera acusado de tal cargo...",
  ui_story_5048_50480302_18_dialog_content = "Se nos dificultaría aún más establecer confianza e intercambiar información con los encargados aquí en el futuro.",
  ui_story_5048_50480302_19_dialog_content = "Su sabiduría me asombra, Su Alteza.",
  ui_story_5048_50480302_20_dialog_content = "¡Lo hiciste!",
  ui_story_5048_50480302_21_dialog_content = "Siéntanse libres de mover sus bocas, ¡pero por favor, mantengan sus manos quietas!",
  ui_story_5048_50480302_22_dialog_content = "¡Agárralo! ¡No dejes que se escape!",
  ui_story_5048_50480302_23_dialog_content = "¡No nos dejemos llevar ahora, todos!",
  ui_story_5048_50480302_24_dialog_content = "Es imperativo contar con pruebas concluyentes antes de hacer acusaciones, y mucho menos antes de exigir castigo. Li Tianxian podría ser el principal sospechoso aquí, pero se deben encontrar pruebas suficientes para condenarlo.",
  ui_story_5048_50480302_25_dialog_content = "Lady, tienes razón, pero ¿cómo encontramos evidencia?",
  ui_story_5048_50480302_26_dialog_content = "¿Puede decirnos, por favor, adónde fue Ernest y qué hizo hoy?",
  ui_story_5048_50480302_27_dialog_content = "Nuestro jefe tiene una rutina diaria muy regular, y hoy no fue diferente.",
  ui_story_5048_50480302_28_dialog_content = "Incluye principalmente inspeccionar la cocina y, a veces, observar los comentarios de los clientes en el restaurante.",
  ui_story_5048_50480302_29_dialog_content = "Entonces, ¿qué comió él hoy?",
  ui_story_5048_50480302_30_dialog_content = "No tiene comidas regulares porque cada plato de la cocina le reserva una muestra para degustar.",
  ui_story_5048_50480302_31_dialog_content = "Los platos solo se llevan a las mesas de los clientes cuando él da su aprobación.",
  ui_story_5048_50480302_32_dialog_content = "Además de esto, ¿estás seguro de que él no comió absolutamente nada más?",
  ui_story_5048_50480302_33_dialog_content = "No, ¡te lo puedo asegurar!",
  ui_story_5048_50480302_34_dialog_content = "En ese caso, el veneno debería estar en la comida que probó Ernest.",
  ui_story_5048_50480302_35_dialog_content = "¿Veneno?",
  ui_story_5048_50480302_36_dialog_content = "Así es. La razón por la que Ernest colapsó fue debido al veneno de llama de cuervo en su organismo.",
  ui_story_5048_50480302_37_dialog_content = "Li Tianxian, ¿entraste a la cocina hoy?",
  ui_story_5048_50480302_38_dialog_content = "Juro por el Pergamino de la Ascensión Divina—¡no!",
  ui_story_5048_50480302_39_dialog_content = "¿Hay algún testigo que pueda testificar sobre esto?",
  ui_story_5048_50480302_40_dialog_content = "Mi benefactor... ¡Sr. Víctor!",
  ui_story_5048_50480302_41_dialog_content = "Comencé a hablar con mi benefactor tan pronto como crucé la puerta. ¡Él puede testificar en mi nombre!",
  ui_story_5048_50480302_42_dialog_content = "Erm... puedo dar fe de esto.",
  ui_story_5048_50480302_43_dialog_content = "¿Qué está pasando... Eso significa que no es culpable?",
  ui_story_5048_50480302_44_dialog_content = "... Si no fue él, entonces ¿quién lo hizo?",
  ui_story_5048_50480302_45_dialog_content = "Muchas gracias por tu ayuda, Princesa Dantang. Sin tu intervención, no habría podido limpiar mi nombre de estas sospechas aunque hubiera saltado de vuelta al océano de donde venimos.",
  ui_story_5048_50480302_46_dialog_content = "No me malinterpretes, no lo hice para ayudarte, simplemente estoy tratando de llegar a la verdad.",
  ui_story_5048_50480302_47_dialog_content = "Si no es él, ¿entonces quién podría ser? Ni siquiera sabemos si nuestro jefe está vivo o muerto. ¿Qué hacemos ahora?",
  ui_story_5048_50480302_48_dialog_content = "No te preocupes. No me rendiré en esto, ya que me he involucrado en este asunto.",
  ui_story_5048_50480302_49_dialog_content = "Señorita, por favor selle la escena con sus colegas y evite tocar incluso una partícula de polvo. Además, debo pedirle que haga una lista de todas las personas que entraron y salieron del restaurante hoy.",
  ui_story_5048_50480302_50_dialog_content = "Vale, gracias... Por cierto, ¿cómo debemos dirigirnos a usted?",
  ui_story_5048_50480302_51_dialog_content = "Llámame simplemente Dantang.",
  ui_story_5048_50480302_52_dialog_content = "Gracias señorita Dantang!",
  ui_story_5048_50480302_53_dialog_content = "Princesa Dantang, eres un alma verdaderamente hermosa y amable, y manejas todo con tanta calma.",
  ui_story_5048_50480302_54_dialog_content = "Te han despejado de sospechas, pero aún no te has esfumado.",
  ui_story_5048_50480302_55_dialog_content = "Puede que no haya sido el culpable, pero todo esto sucedió justo frente a mis ojos. No puedo simplemente quedarme como un observador pasivo.",
  ui_story_5048_50480302_56_dialog_content = "¿Tienes alguna idea de cómo podría resolverse este caso?",
  ui_story_5048_50480302_57_dialog_content = "En cuanto a resolver el caso, tus habilidades son superiores a las mías, así que naturalmente no me atrevería a intentar instruirte sobre cómo manejarlo.",
  ui_story_5048_50480302_58_dialog_content = "Sin embargo, mientras me arañaban las personas hace un momento, escuché algo interesante.",
  ui_story_5048_50480302_59_dialog_content = "Dicen que el dueño de este restaurante, Ernest, nació en una familia con una riqueza tremenda.",
  ui_story_5048_50480302_60_dialog_content = "Pero para cumplir su sueño de crear comida de clase mundial, llegó hasta abrir un restaurante en Twin Pavilions Bay.",
  ui_story_5048_50480302_61_dialog_content = "Establece requisitos extremadamente estrictos para la comida que sirve, y si este restaurante llegara a ocupar el segundo lugar en Twin Pavilions Bay, nadie se atrevería a afirmar que su establecimiento ocupa el primer lugar.",
  ui_story_5048_50480302_62_dialog_content = "¿A quién podría haber ofendido una figura tan prestigiosa?",
  ui_story_5048_50480302_63_dialog_content = "¡Oh, eso podría ser una lista bastante larga!",
  ui_story_5048_50480302_64_dialog_content = "Las habilidades culinarias de Ernest son realmente impecables, pero es un hombre distante y arrogante si alguna vez hubo uno.",
  ui_story_5048_50480302_65_dialog_content = "A menudo regaña a sus aprendices, está constantemente chocando con los comensales e incluso...",
  ui_story_5048_50480302_66_dialog_content = "Si tienes algo que decir, dilo. No es momento de hacer misterio de las cosas.",
  ui_story_5048_50480302_67_dialog_content = "También abrió un café en la azotea sobre el restaurante.",
  ui_story_5048_50480302_68_dialog_content = "Para la gente local aquí, reunirse en un café es lo mismo que salir a comer en Longzhou.",
  ui_story_5048_50480302_69_dialog_content = "Y lo más importante de una comida no es la comida...",
  ui_story_5048_50480302_70_dialog_content = "... Son los temas a discutir durante la comida.",
  ui_story_5048_50480302_71_dialog_content = "Entiendo. Este restaurante probablemente sea uno de los principales puntos de encuentro donde los dignatarios locales discuten asuntos importantes.",
  ui_story_5048_50480302_72_dialog_content = "Gracias por su aporte, Maestro Li.",
  ui_story_5048_50480302_73_dialog_content = "Entonces soy Maestro Li cuando soy útil y un embaucador mercenario cuando no lo soy... Su Alteza, sus habilidades de manipulación superan incluso las mías.",
  ui_story_5048_50480302_74_dialog_content = "Tianxian, no tientes tu suerte.",
  ui_story_5048_50480302_75_dialog_content = "Si este asunto involucra a funcionarios locales, debe ser mucho más complejo de lo que habíamos anticipado previamente.",
  ui_story_5048_50480302_76_dialog_content = "Su Alteza, ¿deberíamos salir de este lío mientras aún podamos?",
  ui_story_5048_50480302_77_dialog_content = "Podríamos dejar el caso al representante del Gremio Umbraton ubicado en Twin Pavilions Bay, el que está trabajando con la familia Lin para mantener el orden aquí.",
  ui_story_5048_50480302_78_dialog_content = "¡No, eso no funcionará en absoluto!",
  ui_story_5048_50480302_79_dialog_content = "Su Alteza aún no ha revelado sus intenciones. ¿De qué estás hablando?",
  ui_story_5048_50480302_80_dialog_content = "Realicé una adivinación para usted hace un momento, Su Alteza...",
  ui_story_5048_50480302_81_dialog_content = "Si permites que este asunto se desarrolle sin tu intervención, te afectará negativamente y dará lugar a ramificaciones interminables.",
  ui_story_5048_50480302_82_dialog_content = "Su Alteza detesta la adivinación. ¿Cómo te atreves a mencionar algo así en su presencia?",
  ui_story_5048_50480302_83_dialog_content = "No importa, Jiu.",
  ui_story_5048_50480302_84_dialog_content = "El asunto ya ha llegado a este punto. No puedo simplemente irme.",
  ui_story_5048_50480302_85_dialog_content = "Somos extraños en esta tierra, así que será difícil para nosotros comenzar a investigar las relaciones interpersonales de los lugareños.",
  ui_story_5048_50480302_86_dialog_content = "Pero aún tenemos una pista a la que hacer seguimiento.",
  ui_story_5048_50480302_87_dialog_content = "¿Qué pista?",
  ui_story_5048_50480302_88_dialog_content = "La hierba, llamarada de cuervo.",
  ui_story_5048_50480401_1_dialog_content = "Disculpe, ¿puedo preguntar si venden una hierba de Longzhou llamada ravenflame aquí?",
  ui_story_5048_50480401_2_dialog_content = "Nop, no tenemos eso.",
  ui_story_5048_50480401_3_dialog_content = "Pero he escuchado a la gente decir que en Twin Pavilions Bay, por muy grande que sea, solo tu tienda vende esta hierba.",
  ui_story_5048_50480401_4_dialog_content = "Puedes comprarlo de quien dijo eso. Nosotros no lo tenemos.",
  ui_story_5048_50480401_5_dialog_content = "Tu actitud es atroz... ¡Me gustaría hablar con el propietario!",
  ui_story_5048_50480401_6_dialog_content = "¿Qué está pasando aquí? Dime cuál es el problema y mantengamos esto amigable, ¿eh?",
  ui_story_5048_50480401_7_dialog_content = "Señora Sheol, están aquí tratando de causar problemas.",
  ui_story_5048_50480401_8_dialog_content = "Ay, querido... ¿Cuántas veces tengo que decírtelo?",
  ui_story_5048_50480401_9_dialog_content = "Cualquiera que entre a esta tienda es un cliente, y los clientes son el cielo arriba, la tierra abajo, la misma carne de nuestros corazones latientes.",
  ui_story_5048_50480401_10_dialog_content = "¿Cómo puedo confiar en ti para cuidar de la sucursal de Twin Pavilions Bay cuando te comportas así?",
  ui_story_5048_50480401_11_dialog_content = "Pero, Señorita Sheol, ¿no dijiste que la hierba es solo para el—",
  ui_story_5048_50480401_12_dialog_content = "Ejem, ¿por qué no vas al fondo y revisas el inventario primero?",
  ui_story_5048_50480401_13_dialog_content = "Mi querida, realmente lo siento mucho por eso. Nuestra nueva asistente de tienda claramente aún no comprende del todo nuestra filosofía de marca.",
  ui_story_5048_50480401_14_dialog_content = "Si te ofendí, lo siento. Permíteme ofrecerte una compensación por tu malestar: todos están invitados a un descuento del doce por ciento al comprar aquí hoy.",
  ui_story_5048_50480401_15_dialog_content = "Solo queremos comprar una hierba llamada ravenflame.",
  ui_story_5048_50480401_16_dialog_content = "Pequeña dama...",
  ui_story_5048_50480401_17_dialog_content = "Solo con mirarte, me doy cuenta de que no estás aquí para comprarlo, ¿verdad?",
  ui_story_5048_50480401_18_dialog_content = "Señora Sheol, parece que nada se te escapa.",
  ui_story_5048_50480401_19_dialog_content = "Pero no vinimos aquí con la intención de causar problemas. Estamos investigando un caso.",
  ui_story_5048_50480401_20_dialog_content = "¿Has oído sobre el incidente relacionado con el Sr. Ernest que ocurrió esta tarde?",
  ui_story_5048_50480401_21_dialog_content = "Ah, sí. Ernest está envuelto en un conflicto entre las facciones proteccionistas y de libre comercio del distrito oeste de Twin Pavilions Bay.",
  ui_story_5048_50480401_22_dialog_content = "Algo así tenía que pasar tarde o temprano.",
  ui_story_5048_50480401_23_dialog_content = "Esperaba que pudieras hacerme un favor, Lady Sheol, y decirme si recuerdas a alguien comprando alguna ravenflame.",
  ui_story_5048_50480401_24_dialog_content = "De esa manera, podríamos encontrar al verdadero culpable y asegurar un ambiente comercial estable en Twin Pavilions Bay.",
  ui_story_5048_50480401_25_dialog_content = "El entorno empresarial local no se estabilizará resolviendo este caso únicamente. Lo último que un empresario como yo puede permitirse es molestar a mis clientes, así que por favor no me compliques aún más las cosas.",
  ui_story_5048_50480401_26_dialog_content = "Mi bella dama, me temo que no reconoces quién está frente a ti.",
  ui_story_5048_50480401_27_dialog_content = "Estás en presencia de la Princesa Zhuohua de Longzhou, Su Alteza Dantang, un enviado diplomático de la nación nombrado por los altos mandos.",
  ui_story_5048_50480401_28_dialog_content = "Si la ofendes, puedes olvidarte de vender más ravenflame. De hecho, es posible que te resulte imposible conseguir productos de Longzhou en el futuro.",
  ui_story_5048_50480401_29_dialog_content = "Pero si tengo productos y no hay clientes, de todos modos no podré hacer negocios.",
  ui_story_5048_50480401_30_dialog_content = "Si ese es el caso, quizás podamos ser sus clientes, Señora Sheol?",
  ui_story_5048_50480401_30X1_dialog_content = "Pequeña Lady, sería un honor. Además de ravenflame, tenemos una amplia gama de otros productos más diversos de lo que puedas imaginar.",
  ui_story_5048_50480401_30X2_dialog_content = "Una amplia gama de productos, ¿eh?",
  ui_story_5048_50480401_31_dialog_content = "Siguiendo esta línea de pensamiento, ¿podrías decir que la información sobre la persona que compró ravenflame podría considerarse un artículo comercializable en tu tienda?",
  ui_story_5048_50480401_32_dialog_content = "¡Jajaja! Esta mercancía en particular es un poco complicada, pero si realmente eres tan sincero en tus intenciones, no puedo quedarme de brazos cruzados y no hacer nada.",
  ui_story_5048_50480401_33_dialog_content = "Lady Sheol, tenga la seguridad de que mientras el precio sea razonable, le daré el efectivo en este momento.",
  ui_story_5048_50480401_34_dialog_content = "¡Ustedes, princesas de Longzhou, ciertamente van al grano! Sin embargo, el precio de este artículo no es dinero, sino una persona.",
  ui_story_5048_50480401_35_dialog_content = "¿Una persona?",
  ui_story_5048_50480401_36_dialog_content = "Hace unos días, estallaron disturbios en el bazar de mercenarios cerca de Twin Pavilions Bay, lo que me llevó a perder una gran cantidad de mercancías.",
  ui_story_5048_50480401_37_dialog_content = "Pero nadie se atreve a dar un paso adelante y asumir la responsabilidad del asunto.",
  ui_story_5048_50480401_38_dialog_content = "Todo lo que tengo para guiarme es un rumor de que una persona misteriosa no identificada apareció en la escena del disturbio.",
  ui_story_5048_50480401_39_dialog_content = "He estado esperando que alguien me ayude a encontrar a esta persona misteriosa y descubrir la verdad detrás del disturbio.",
  ui_story_5048_50480401_40_dialog_content = "¿Este sinvergüenza tiene alguna característica distintiva?",
  ui_story_5048_50480401_41_dialog_content = "Dicen que la persona misteriosa empuñaba una espada pesada, llevaba una capa oscura y estaba cubierta de pinchos extremadamente afilados.",
  ui_story_5048_50480401_42_dialog_content = "Vaya, esta no es una persona ordinaria.",
  ui_story_5048_50480401_43_dialog_content = "Ajá. Si vas a buscar a esta persona o no, depende de ti.",
  ui_story_5048_50480401_44_dialog_content = "Tengo asuntos que atender ahora mismo, pero siéntete libre de quedarte en la tienda todo el tiempo que quieras. Si necesitas algo más, solo avisa al dependiente y le recordaré que te haga un descuento.",
  ui_story_5048_50480401_45_dialog_content = "Muchas gracias, Señora Sheol.",
  ui_story_5048_50480401_46_dialog_content = "¡Oh, es cierto!",
  ui_story_5048_50480401_47_dialog_content = "Si encuentras a esa persona misteriosa, ¡asegúrate de tratarla bien!",
  ui_story_5048_50480401_48_dialog_content = "¿Por qué querríamos tratar bien a un villano así? Esta Señorita Sheol suena como Tianxian... Debo admitir que estoy bastante confundido.",
  ui_story_5048_50480401_49_dialog_content = "Las cosas de las que hablo son misterios de la naturaleza, cosas que naturalmente son difíciles de entender.",
  ui_story_5048_50480401_50_dialog_content = "En cuanto a las formas misteriosas de esta Señora Sheol, ¡no puedo decir si está siendo ambigua deliberadamente o intencionalmente!",
  ui_story_5048_50480401_51_dialog_content = "Deliberadamente o intencionalmente... ¿No son lo mismo?",
  ui_story_5048_50480401_52_dialog_content = "Bueno, esencialmente, ahora recae en Su Alteza y la Srta. Jiu buscar a esta persona misteriosa.",
  ui_story_5048_50480401_53_dialog_content = "Puede que sea hábil con el ingenio y las palabras, pero manejar armas es un trabajo... mejor dejado a aquellos con más experiencia.",
  ui_story_5048_50480401_54_dialog_content = "Volveré al restaurante y esperaré las buenas noticias!",
  ui_story_5048_50480401_55_dialog_content = "Entonces incluso el Maestro Li tiene sus momentos de temor.",
  ui_story_5048_50480401_56_dialog_content = "Como dice el refrán, un hombre sabio conoce sus límites y elige sus batallas; solo así puede convertirse en un héroe. Además, yo tampoco estaré de brazos cruzados.",
  ui_story_5048_50480401_57_dialog_content = "Cuando se trata de investigar rumores y determinar los hechos de la situación, todavía tengo algunos trucos bajo la manga.",
  ui_story_5048_50480401_58_dialog_content = "Muy bien, dividámonos y sigamos adelante, quizás avancemos más rápido. Maestro Li, muchas gracias.",
  ui_story_5048_50480401_59_dialog_content = "Por supuesto.",
  ui_story_5048_50480401_60_dialog_content = "Su Alteza, el bazar de mercenarios está justo adelante.",
  ui_story_5048_50480401_61_dialog_content = "Es mucho más grande de lo que esperaba, pero eso no debería ser un problema. Hagamos todas las consultas que podamos y busquemos testigos de los eventos recientes aquí.",
  ui_story_5048_50480401_62_dialog_content = "¡Ahh! ¡Los Eclipsites están aquí!",
  ui_story_5048_50480401_63_dialog_content = "¿Eclipsites otra vez? Y tan pronto después del último ataque...",
  ui_story_5048_50480401_64_dialog_content = "¡Rugido!",
  ui_story_5048_50480401_65_dialog_content = "¡Tenga cuidado, Su Alteza!",
  ui_story_5048_50480401_66_dialog_content = "¡Toma las espinas!",
  ui_story_5048_50480401_67_dialog_content = "¡Su Alteza, está herido?!",
  ui_story_5048_50480401_68_dialog_content = "No. Esa chica de repente se acercó a mí y me ayudó a bloquear el ataque de los Eclipsites justo ahora.",
  ui_story_5048_50480401_69_dialog_content = "Esa chica...",
  ui_story_5048_50480401_70_dialog_content = "Empuñando una espada pesada, llevando una capa y cubierto de espinas?",
  ui_story_5048_50480401_71_dialog_content = "¡Ella es la que estamos buscando!",
  ui_story_5048_50480401_72_dialog_content = "Adelante, la detendré ahora mismo.",
  ui_story_5048_50480401_73_dialog_content = "Jiu, no seas precipitado.",
  ui_story_5048_50480401_74_dialog_content = "¿Por qué no? ¿No es ella la persona que estamos buscando?",
  ui_story_5048_50480401_75_dialog_content = "Ella es la persona que buscamos, pero solo mírala con su postura erguida y expresión decidida...",
  ui_story_5048_50480401_76_dialog_content = "No parece alguien que cometería actos malvados intencionalmente.",
  ui_story_5048_50480401_77_dialog_content = "Mmm...",
  ui_story_5048_50480401_78_dialog_content = "¡Graagh!",
  ui_story_5048_50480401_79_dialog_content = "¡Que haya luz!",
  ui_story_5048_50480401_80_dialog_content = "Por la forma en que persigue a estos Eclipsites y protege a los transeúntes, creo que es seguro asumir que ella es una persona justa.",
  ui_story_5048_50480401_81_dialog_content = "¿Recuerdas lo que dijo la Señora Sheol?",
  ui_story_5048_50480401_82_dialog_content = "Si encuentras a esa persona misteriosa, ¡asegúrate de tratarla bien!",
  ui_story_5048_50480401_83_dialog_content = "Probablemente ella no sea la instigadora de los problemas recientes aquí, sino alguien que busca justicia, como nosotros.",
  ui_story_5048_50480401_84_dialog_content = "Si ese es el caso, le echaré una mano.",
  ui_story_5048_50480401_85_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5048_50480401_86_dialog_content = "Uf... uf... uf...",
  ui_story_5048_50480401_87_dialog_content = "Noble guerrero, por favor descansa un rato—",
  ui_story_5048_50480401_88_dialog_content = "A-¿Estás aquí para atraparme también?",
  ui_story_5048_50480401_89_dialog_content = "Lo siento por asustarte. Somos del continente de Longzhou y Lady Sheol nos ha confiado en esta tierra para investigar la causa del caos en el bazar hace varios días.",
  ui_story_5048_50480401_90_dialog_content = "¿Puedes decirnos qué está pasando aquí?",
  ui_story_5048_50480401_91_dialog_content = "Señorita Sheol...?",
  ui_story_5048_50480401_92_dialog_content = "Aquí hay todo tipo de personas, no solo mercenarios y criminales, sino también...",
  ui_story_5048_50480401_93_dialog_content = "¡Graagh!",
  ui_story_5048_50480401_94_dialog_content = "Tose... Y todavía tenemos a estos Eclipsites rompiendo nuestras defensas.",
  ui_story_5048_50480401_95_dialog_content = "Un lugar como este... manchará el borde de las prendas de una noble tan hermosa.",
  ui_story_5048_50480401_96_dialog_content = "Mientras no haya otros Eclipsites atacando... aprovecha esta oportunidad y regresa a casa lo más rápido que puedas.",
  ui_story_5048_50480401_97_dialog_content = "Si puedo demostrar que una mujer noble puede pelear como un mercenario, ¿cambiarás de opinión y me ayudarás?",
  ui_story_5048_50480401_98_dialog_content = "¡Rugido!",
  ui_story_5048_50480401_99_dialog_content = "... ¡E-Está bien! ¡Te dejo esto a ti!",
  ui_story_5048_50480402_1_dialog_content = "Terminé de revisar, no se escapó ni uno solo.",
  ui_story_5048_50480402_2_dialog_content = "Gracias por estar tan dispuesto a ayudarme...",
  ui_story_5048_50480402_3_dialog_content = "Pensé que mi apariencia... podría asustarte.",
  ui_story_5048_50480402_4_dialog_content = "Puedo ver claramente que eres muy encantadora y adorable. Me recuerdas a mi hermana menor. ¿Cómo podrías asustarme?",
  ui_story_5048_50480402_5_dialog_content = "Estas... espinas... en mi cuerpo...",
  ui_story_5048_50480402_6_dialog_content = "¿Les duele?",
  ui_story_5048_50480402_7_dialog_content = "Estoy... acostumbrado a ellos.",
  ui_story_5048_50480402_8_dialog_content = "Aunque estas espinas te causen dolor, también puedes usarlas para luchar y ayudar a quienes lo necesitan...",
  ui_story_5048_50480402_9_dialog_content = "¡Tu apariencia es realmente admirable!",
  ui_story_5048_50480402_10_dialog_content = "Oh...",
  ui_story_5048_50480402_11_dialog_content = "Soy Dantang y aquí a mi lado está Jiu.",
  ui_story_5048_50480402_12_dialog_content = "Somos de Longzhou y actualmente estamos investigando un caso aquí.",
  ui_story_5048_50480402_13_dialog_content = "La Señorita Sheol nos dijo que quizás usted podría saber algo, por eso nos tomamos la libertad de venir aquí a buscarle.",
  ui_story_5048_50480402_14_dialog_content = "Entonces... es por eso que estás aquí.",
  ui_story_5048_50480402_15_dialog_content = "¿Puedes decirnos tu nombre ahora?",
  ui_story_5048_50480402_16_dialog_content = "Areia...",
  ui_story_5048_50480402_17_dialog_content = "Mi nombre es Areia.",
  ui_story_5048_50480501_1_dialog_content = "Señorita Areia, cuando mencionaste hace un momento que alguien te perseguía, ¿estabas diciendo la verdad?",
  ui_story_5048_50480501_2_dialog_content = "Puedes contarnos al respecto, si no te importa, claro.",
  ui_story_5048_50480501_3_dialog_content = "Ehm... N-No me juzgues por mi apariencia, en realidad soy un mercenario errante.",
  ui_story_5048_50480501_4_dialog_content = "He tenido que vivir con una enfermedad terrible desde que nací: estas espinas negras que crecen en mi cuerpo.",
  ui_story_5048_50480501_5_dialog_content = "Así que ahora deambulo de un lugar a otro, con la esperanza de encontrar una forma de curar mi condición.",
  ui_story_5048_50480501_6_dialog_content = "Llegué a Twin Pavilions Bay hace poco tiempo.",
  ui_story_5048_50480501_7_dialog_content = "Me encontré con un empleador que paga bien en el bazar de mercenarios.",
  ui_story_5048_50480501_8_dialog_content = "Oye, solo mírate...",
  ui_story_5048_50480501_9_dialog_content = "¿Conoces algún truco para lastimar sin dejar rastro?",
  ui_story_5048_50480501_10_dialog_content = "No sé de esas cosas...",
  ui_story_5048_50480501_11_dialog_content = "Confía en mí, el pago te hará feliz.",
  ui_story_5048_50480501_12_dialog_content = "Nunca lastimaría a nadie sin una buena razón...",
  ui_story_5048_50480501_13_dialog_content = "Humph, ¿intentando actuar todo altivo y recto aquí?",
  ui_story_5048_50480501_14_dialog_content = "Personas como tú hay a montones; no eres nada especial.",
  ui_story_5048_50480501_15_dialog_content = "¿Gente... me gusta...?",
  ui_story_5048_50480501_16_dialog_content = "Pensé que si lo seguía, podría encontrar personas afectadas por la misma condición que yo, y quizás podrían decirme qué causa este tipo de enfermedad terrible.",
  ui_story_5048_50480501_17_dialog_content = "Pero más tarde descubrí... que él no conocía a nadie que entendiera estas cosas.",
  ui_story_5048_50480501_18_dialog_content = "De hecho, resultó que había encontrado otra forma de llevar a cabo sus planes.",
  ui_story_5048_50480501_19_dialog_content = "Pero, ¿no renunciaste a tu búsqueda solo por esto?",
  ui_story_5048_50480501_20_dialog_content = "Simplemente no podía quedarme de brazos cruzados... y ver cómo la gente salía lastimada, así que seguí buscando por mi cuenta.",
  ui_story_5048_50480501_21_dialog_content = "Pero fui demasiado descuidado... Me expuse en el bazar hace unos días.",
  ui_story_5048_50480501_22_dialog_content = "El problema en el bazar fue en realidad el resultado de que él me atrapara.",
  ui_story_5048_50480501_23_dialog_content = "Entonces, ¿esos Eclipsites fueron traídos aquí por ese empleador?",
  ui_story_5048_50480501_24_dialog_content = "Lo siento mucho, mucho... ¡Todo esto es mi culpa!",
  ui_story_5048_50480501_25_dialog_content = "Entonces, no puedo simplemente rendirme y dejar que su plan tenga éxito.",
  ui_story_5048_50480501_26_dialog_content = "Parece que los derechos y los errores aquí no son menos que en Longzhou.",
  ui_story_5048_50480501_27_dialog_content = "El camino del mundo es buscar el beneficio personal.",
  ui_story_5048_50480501_28_dialog_content = "Con tanto dinero fluyendo en los canales comerciales de Twin Pavilions Bay, ¿cómo no iba a atraer tanto a lo bueno como a lo malo?",
  ui_story_5048_50480501_29_dialog_content = "Pero apenas acabamos de llegar. ¿Por qué ya nos hemos encontrado con tantos sucesos extraños?",
  ui_story_5048_50480501_30_dialog_content = "... Tienes un buen punto, Jiu. Quizás estos no sean incidentes aislados. Puede que haya alguna conexión oculta entre ellos...",
  ui_story_5048_50480501_31_dialog_content = "Areia, ¿has descubierto alguna información útil durante tu investigación?",
  ui_story_5048_50480501_32_dialog_content = "Hmm... El empleador que mencioné es el jefe de un grupo comercial en el distrito oeste de Twin Pavilions Bay.",
  ui_story_5048_50480501_33_dialog_content = "Él es miembro de lo que los lugareños llaman la facción del libre comercio y tiene un fuerte odio hacia los proteccionistas...",
  ui_story_5048_50480501_34_dialog_content = "Entonces, su objetivo es alguien de la facción proteccionista.",
  ui_story_5048_50480501_35_dialog_content = "Todo está conectado.",
  ui_story_5048_50480501_36_dialog_content = "Recuerdo que Lady Sheol mencionó que Ernest está envuelto en un conflicto entre las facciones proteccionistas y de libre comercio.",
  ui_story_5048_50480501_37_dialog_content = "En realidad... descubrí la identidad del objetivo durante mi investigación... Quería enfrentarme a los Eclipsites e ir a buscar a un hombre llamado Víctor.",
  ui_story_5048_50480501_38_dialog_content = "¿Qué dijiste?",
  ui_story_5048_50480501_39_dialog_content = "El objetivo era... el Sr. Victor, el representante del Gremio Umbraton asignado a Twin Pavilions Bay.",
  ui_story_5048_50480501_40_dialog_content = "Oh no...",
  ui_story_5048_50480501_41_dialog_content = "Víctor es el nombre del benefactor de Tianxian!",
  ui_story_5048_50480501_42_dialog_content = "¡A-Achoo!",
  ui_story_5048_50480501_43_dialog_content = "Maestro Li, ¿estás bien?",
  ui_story_5048_50480501_44_dialog_content = "No es nada, por favor, continúa.",
  ui_story_5048_50480501_45_dialog_content = "... Así que, por supuesto, encuentro todo esto muy angustiante, ya que Ernest es mi amigo y la única persona que me impulsa a ser más resuelto.",
  ui_story_5048_50480501_46_dialog_content = "Aunque tiene una lengua afilada y a veces respondo con algunas críticas propias, sé que su punto de vista suele ser bastante razonable.",
  ui_story_5048_50480501_47_dialog_content = "Aún no está al tanto de esto, pero ya he comenzado a impulsar las prácticas de los proteccionistas, con el objetivo de hacerlas conocidas por todos.",
  ui_story_5048_50480501_48_dialog_content = "Pero ahora, si realmente está acabado, los proteccionistas se quedarán sin su defensor más influyente...",
  ui_story_5048_50480501_49_dialog_content = "Tal vez debería reconsiderar mi elección de apoyar a los proteccionistas.",
  ui_story_5048_50480501_50_dialog_content = "Como representante del Gremio Umbraton en Twin Pavilions Bay, el Sr. Victor siempre ha sido conocido por su actitud despreocupada hacia los grupos comerciales.",
  ui_story_5048_50480501_51_dialog_content = "Recientemente, sin embargo, decidió no hacer la vista gorda.",
  ui_story_5048_50480501_52_dialog_content = "También planeaba promover las propuestas de los proteccionistas, convirtiéndose así en un objetivo para los defensores del libre comercio.",
  ui_story_5048_50480501_53_dialog_content = "Pero el Sr. Víctor no fue la víctima de la trama hace un momento. En cambio, el dueño del restaurante, Ernesto, fue envenenado y colapsó.",
  ui_story_5048_50480501_54_dialog_content = "¿Podrían los comerciantes libres haber tenido dos objetivos?",
  ui_story_5048_50480501_55_dialog_content = "Jiu, ¿recuerdas cómo Ernest solía probar toda la comida que salía de la cocina?",
  ui_story_5048_50480501_56_dialog_content = "El camarero del restaurante sí mencionó este hecho.",
  ui_story_5048_50480501_57_dialog_content = "El Sr. Victor no tuvo tiempo para comer porque Tianxian estaba adivinando para él.",
  ui_story_5048_50480501_58_dialog_content = "... El asesino manipuló la comida de Víctor.",
  ui_story_5048_50480501_59_dialog_content = "Ernest fue envenenado porque probó los platos de Víctor y terminó siendo la víctima en lugar del objetivo previsto!",
  ui_story_5048_50480501_60_dialog_content = "Si este aspirante a asesino hubiera sabido de antemano que Ernest, un proteccionista, tenía la costumbre de probar la comida antes de servirla...",
  ui_story_5048_50480501_61_dialog_content = "El envenenamiento habría sido la estrategia perfecta para matar dos pájaros de un tiro.",
  ui_story_5048_50480501_62_dialog_content = "Entonces resulta que Tianxian en realidad puede salvar vidas a veces.",
  ui_story_5048_50480501_63_dialog_content = "Hablando de eso, Srta. Areia... ¿dijiste hace un momento que el culpable ha vuelto al bazar de mercenarios?",
  ui_story_5048_50480501_64_dialog_content = "Ehm... todavía está buscando a alguien que lo ayude a deshacerse de Victor.",
  ui_story_5048_50480501_65_dialog_content = "¿Todavía sigue esta conspiración en contra de Víctor?",
  ui_story_5048_50480501_66_dialog_content = "¡Ayuda! ¡Ayuda!",
  ui_story_5048_50480501_67_dialog_content = "¡A las puertas de la muerte!",
  ui_story_5048_50480501_68_dialog_content = "¡Rugido!",
  ui_story_5048_50480501_69_dialog_content = "¿No dijiste que conocería a una persona virtuosa que convertiría las desgracias en bendiciones?",
  ui_story_5048_50480501_70_dialog_content = "¡Todo lo que veo aquí son Eclipsites! ¿Dónde está mi virtuoso salvador?!",
  ui_story_5048_50480501_71_dialog_content = "Ah, tampoco pensé que las cosas saldrían así. La persona virtuosa destinada a salvar tu vida no era un noble de Lumopolis, ni tampoco la Princesa de Longzhou...",
  ui_story_5048_50480501_72_dialog_content = "Fui yo, un adivino sin vergüenza. ¡Lo siento mucho!",
  ui_story_5048_50480601_1_dialog_content = "¡Sr. Victor!",
  ui_story_5048_50480601_2_dialog_content = "¡Señorita Dantang!",
  ui_story_5048_50480601_3_dialog_content = "¿Estás bien? ¿No estás herido en absoluto?",
  ui_story_5048_50480601_4_dialog_content = "Estoy bien, no estoy herido...",
  ui_story_5048_50480601_5_dialog_content = "¿Y dónde está Tianxian?",
  ui_story_5048_50480601_6_dialog_content = "El Maestro Li se llevó a todos los Eclipsites por sí mismo para salvarme...",
  ui_story_5048_50480601_7_dialog_content = "Por favor, rescátalo antes de que sea demasiado tarde!",
  ui_story_5048_50480601_8_dialog_content = "¿Por qué no pudo predecir que se encontraría cara a cara con el desastre hoy?",
  ui_story_5048_50480601_9_dialog_content = "Me alegra que finalmente hayas aprendido a contar un chiste, pero ahora no es el momento.",
  ui_story_5048_50480601_10_dialog_content = "Lo siento, Su Alteza. Me temo que él pudo haber arrojado su vida en un intento de demostrar su valentía.",
  ui_story_5048_50480601_11_dialog_content = "... ¡Vamos a seguir y echar un vistazo!",
  ui_story_5048_50480601_12_dialog_content = "Jiu, ¡mira!",
  ui_story_5048_50480601_13_dialog_content = "¡Rugido! ¡¡¡Rugido!!!",
  ui_story_5048_50480601_14_dialog_content = "¿Por qué estos Eclipsites se agrupan y rugen hacia el suelo?",
  ui_story_5048_50480601_15_dialog_content = "Es como si estuvieran rodeando a alguien... Espera, ¿podría ser...",
  ui_story_5048_50480601_16_dialog_content = "¡Graaagh!",
  ui_story_5048_50480601_17_dialog_content = "¡Nos vieron!",
  ui_story_5048_50480601_18_dialog_content = "¡Entonces acabemos con ellos rápidamente!",
  ui_story_5048_50480602_1_dialog_content = "Tianxian...",
  ui_story_5048_50480602_2_dialog_content = "Extraño, ¿no está aquí?",
  ui_story_5048_50480602_3_dialog_content = "¿Mmm?",
  ui_story_5048_50480602_4_dialog_content = "Jejeje...",
  ui_story_5048_50480602_5_dialog_content = "Jiu, mira de nuevo. ¿Qué estaban rodeando los Eclipsites hace un momento?",
  ui_story_5048_50480602_6_dialog_content = "Una tapa de alcantarilla que conduce hacia las alcantarillas...",
  ui_story_5048_50480602_7_dialog_content = "¿Hay una figurita de azúcar atascada en ello?",
  ui_story_5048_50480602_8_dialog_content = "Parece que ya hizo su astuta huida, así que no tenemos que preocuparnos más.",
  ui_story_5048_50480602_9_dialog_content = "¡Señorita Dantang!",
  ui_story_5048_50480602_10_dialog_content = "Areia?",
  ui_story_5048_50480602_11_dialog_content = "¿Cuál es la situación? ¿Se ha informado a la Señora Sheol de lo que está pasando?",
  ui_story_5048_50480602_12_dialog_content = "¡Sí! También...",
  ui_story_5048_50480602_13_dialog_content = "Además, traje a los gremios conmigo.",
  ui_story_5048_50480602_14_dialog_content = "Señorita Sheol...",
  ui_story_5048_50480602_15_dialog_content = "Por fin nos volvemos a encontrar, pequeña señorita.",
  ui_story_5048_50480602_16_dialog_content = "Señora Sheol, muchas gracias por su oportuna aparición. Ahora que estamos todos aquí, apresurémonos a atrapar a ese culpable.",
  ui_story_5048_50480602_17_dialog_content = "No te preocupes por eso. Como nos ayudaste a encontrar al testigo clave...",
  ui_story_5048_50480602_18_dialog_content = "El Gremio Umbraton, en conjunto con organizaciones como el Gremio Lin y la Unión de Mensajeros, atrapó rápidamente al culpable.",
  ui_story_5048_50480602_19_dialog_content = "Tal como predijiste, él admitió ser también el responsable de planear el caos de los Eclipsites últimamente.",
  ui_story_5048_50480602_20_dialog_content = "Ahora, en nombre de nuestras guildas, agradecemos solemnemente su invaluable ayuda, Enviada de Longzhou, Princesa Dantang.",
  ui_story_5048_50480602_21_dialog_content = "¡Gracias, princesa Dantang, por eliminar a los malhechores para nosotros!",
  ui_story_5048_50480602_22_dialog_content = "¡Gracias, Princesa Dantang! ¡Gracias, Princesa Dantang!",
  ui_story_5048_50480602_23_dialog_content = "Tengo la sensación de que Lady Sheol sabía quién era el verdadero culpable desde el principio... pero quería que hiciéramos el arresto en nuestro nombre.",
  ui_story_5048_50480602_24_dialog_content = "Twin Pavilions Bay originalmente estaba dividida en dos partes y era gobernada por la Guilda Umbraton y la Guilda Lin.",
  ui_story_5048_50480602_25_dialog_content = "Sus intereses en conflicto están tan entrelazados que me temo que ni ellos mismos pudieron resolver el asunto.",
  ui_story_5048_50480602_26_dialog_content = "Nosotros, siendo forasteros, atrapamos al culpable y así nos convertimos en su escudo.",
  ui_story_5048_50480602_27_dialog_content = "Entonces, ¿nos estaban utilizando?",
  ui_story_5048_50480602_28_dialog_content = "Los beneficios derivados de esta resolución no son unilaterales, también nos han ayudado a nosotros.",
  ui_story_5048_50480602_29_dialog_content = "Ahora hemos establecido nuestra reputación, poco después de llegar a Twin Pavilions Bay. Esto hará que las cosas sean mucho más fáciles para nosotros en el futuro.",
  ui_story_5048_50480602_30_dialog_content = "Señoritas, ¿han terminado de susurrarse entre ustedes allá?",
  ui_story_5048_50480602_31_dialog_content = "Si hay algo con lo que no estés satisfecho, no dudes en decírmelo. Los representantes del gremio están aquí y seguramente te ayudarán a resolver cualquier problema que puedas tener.",
  ui_story_5048_50480602_32_dialog_content = "Ya han hecho mucho, Lady Sheol y todos.",
  ui_story_5048_50480602_33_dialog_content = "Me estaba preguntando, ¿cómo vamos a manejar la disputa entre los comerciantes libres y los proteccionistas en Twin Pavilions Bay en el futuro?",
  ui_story_5048_50480602_34_dialog_content = "He estado pensando mucho en eso hoy y finalmente he llegado a entender algo.",
  ui_story_5048_50480602_35_dialog_content = "Todos podemos estar de acuerdo en que Twin Pavilions Bay necesita sistemas justos y controles adecuados.",
  ui_story_5048_50480602_36_dialog_content = "Independientemente de si hay apoyo de la otra facción comercial en el futuro, continuaré promoviendo las propuestas de los proteccionistas.",
  ui_story_5048_50480602_37_dialog_content = "Incluso si esto impone ciertas restricciones en las actividades e intereses de otras facciones existentes.",
  ui_story_5048_50480602_38_dialog_content = "Restricciones...",
  ui_story_5048_50480602_39_dialog_content = "<color=#e8d9bb>Chirrido, chirrido, chirrido—</color>",
  ui_story_5048_50480602_39X1_dialog_content = "<color=#e8d9bb>Sheol mira al cielo con una expresión pensativa.</color>",
  ui_story_5048_50480602_40_dialog_content = "Todas estas restricciones llevarán a beneficios mucho mayores.",
  ui_story_5048_50480602_41_dialog_content = "¿Qué opinas, pequeña dama?",
  ui_story_5048_50480602_42_dialog_content = "Mmm, no tengo objeciones.",
  ui_story_5048_50480602_43_dialog_content = "Bueno, tener el apoyo de la Princesa de Longzhou me hace sentir aún más tranquilo.",
  ui_story_5048_50480602_44_dialog_content = "¿Pero no tienes miedo de enfrentarte a intentos de difamación por parte de facciones opositoras en el futuro?",
  ui_story_5048_50480602_45_dialog_content = "Miedo... Claro que tengo miedo.",
  ui_story_5048_50480602_46_dialog_content = "Quizás debería considerar contratar a un guardaespaldas como tú.",
  ui_story_5048_50480602_47_dialog_content = "Pero como dijo el Maestro Li, nací bajo una estrella afortunada y siempre puedo contar con la ayuda de benefactores virtuosos para convertir mis desgracias en bendiciones...",
  ui_story_5048_50480602_48_dialog_content = "Oye, ¿por qué no le pido al Maestro Li que sea mi guardaespaldas?",
  ui_story_5048_50480602_49_dialog_content = "Ejem, te aconsejo que lo reconsideres.",
  ui_story_5048_50480602_50_dialog_content = "¡A-Achoo!",
  ui_story_5048_50480602_51_dialog_content = "Juzgando por todos los estornudos, debe haber muchas personas pensando en mí hoy... pero, ¿por qué nadie ha venido a pedirme una adivinación?",
  ui_story_5048_50480602_52_dialog_content = "<color=#e8d9bb>Splish, chapoteo</color>",
  ui_story_5048_50480602_53_dialog_content = "La Princesa de Ye, el Príncipe de Ji... El Incidente de la Familia Lin, ¿El Shadowind?",
  ui_story_5048_50480602_54_dialog_content = "Tch, necesito resolver esto cuidadosamente.",
  ui_story_5048_50480602_55_dialog_content = "<color=#e8d9bb>¡¡Whoooosh!</color>",
  ui_story_5048_50480602_56_dialog_content = "Serpiente Yang arriba, Buey Yin abajo. La primavera da lugar al Buey y la Serpiente, preparándose para cuatro estaciones de tumulto. ¿Podría ser que Longzhou...",
  ui_story_5048_50480602_57_dialog_content = "No, eso no puede ser correcto. Debo estar demasiado cansado para la adivinación ahora mismo... ¿verdad?",
  ui_story_5048_50480602_58_dialog_content = "¡Aquí está! ¡Aquí está!",
  ui_story_5048_50480602_59_dialog_content = "¡Comiendo solo! ¡Comiendo solo!",
  ui_story_5048_50480602_60_dialog_content = "¿De qué hablas? Aún no he comido nada, solo he estado esperando por ustedes dos.",
  ui_story_5048_50480602_61_dialog_content = "¡Quemado! ¡Quemado!",
  ui_story_5048_50480602_62_dialog_content = "¡Encuentra Dantang! ¡Encuentra Dantang!",
  ui_story_5048_50480602_63_dialog_content = "¡Cuida tu pequeño pico! ¡Recuerda llamarla Princesa Dantang cuando salgas!",
  ui_story_5048_50480602_64_dialog_content = "¿Princesa?",
  ui_story_5048_50480602_65_dialog_content = "¿Princesa?",
  ui_story_5048_50480602_66_dialog_content = "Je, este tipo de cosa no es opcional.",
  ui_story_5048_50480602_67_dialog_content = "Como mencionó anteriormente el Gremio Lin, soy Dantang, Enviado del Reino Ji de Longzhou.",
  ui_story_5048_50480602_68_dialog_content = "Hoy estoy aquí, representando los recursos y la buena voluntad que se pueden proporcionar desde el otro lado del mar.",
  ui_story_5048_50480602_69_dialog_content = "Esperamos que esta ruta comercial transoceánica no solo consolide las comunicaciones con los gremios de Umbraton...",
  ui_story_5048_50480602_70_dialog_content = "Pero también puede llegar a Lumopolis, la Federación Illumina e incluso a las lejanas tierras de Northland.",
  ui_story_5048_50480602_71_dialog_content = "...",
  ui_story_5048_50480602_72_dialog_content = "Por supuesto, la cultura y los productos de Astra también pueden ingresar al vasto continente de Longzhou a través de esta ruta comercial.",
  ui_story_5048_50480602_72X1_dialog_content = "El equipo único y los recursos de Astra también pueden ayudar a Longzhou a superar las amenazas en la costa...",
  ui_story_5048_50480602_73_dialog_content = "En resumen, ¡este es un canal de comercio que puede conectar dos continentes!",
  ui_story_5048_50480602_74_dialog_content = "Damas y caballeros, esto no es solo un sueño, sino una realidad a nuestro alcance.",
  ui_story_5048_50480602_75_dialog_content = "Los primeros en adoptar pueden aprovechar esta oportunidad para embarcarse en un camino destinado a perdurar a través de los tiempos.",
  ui_story_5048_50480602_76_dialog_content = "Con su existencia, nuestra lucha contra esas criaturas de la oscuridad también dará paso a más oportunidades.",
  ui_story_5048_50480602_77_dialog_content = "¡Está bien!",
  ui_story_5048_50480602_78_dialog_content = "Bien dicho. Hacía mucho tiempo que no escuchaba palabras tan esperanzadoras.",
  ui_story_5048_50480602_79_dialog_content = "Señor Sombrío... ¡El Señor Sombrío también está aquí!",
  ui_story_5048_50480602_80_dialog_content = "¡El gobernante de Umbraton, Lord Istvan!",
  ui_story_5048_50480602_81_dialog_content = "Acepto con gusto tu valentía y sinceridad, en nombre de mi organización.",
  ui_story_5048_50480602_82_dialog_content = "Veamos si los frutos de nuestra cooperación pueden realmente llevar el futuro de nuestros dos continentes.",
  ui_story_5048_50480602_83_dialog_content = "Creo que al menos servirá como un comienzo.",
  ui_story_5048_50480602_84_dialog_content = "Un buen comienzo para una nueva era.",
  ui_story_5048_50480602_85_dialog_content = "<color=#e8d9bb>Whoosh, whoosh—</color>",
  ui_story_5048_50480602_86_dialog_content = "El viento aumenta.",
  ui_story_5048_50480602_87_dialog_content = "Una dulce lluvia suaviza Twin Pavilions Bay...",
  ui_story_5048_50480602_88_dialog_content = "Pronto viene.",
  ui_story_5048_50480701_1_dialog_content = "<color=#e8d9bb> Unos días después...</color>",
  ui_story_5048_50480701_2_dialog_content = "Su Alteza, este camino de montaña está lleno de peligros, ¡por favor tenga cuidado!",
  ui_story_5048_50480701_3_dialog_content = "Las mejores hierbas suelen crecer en los lugares más peligrosos.",
  ui_story_5048_50480701_4_dialog_content = "Cuando era joven, toda mi familia contrajo la peste y fuimos a las cumbres de montañas más peligrosas para recolectar hierbas.",
  ui_story_5048_50480701_5_dialog_content = "El terreno actual, con sus pequeñas colinas, no es un problema en lo más mínimo.",
  ui_story_5048_50480701_6_dialog_content = "Cielos... Su Alteza, tal vez usted no esté cansado, pero nos ha agotado a todos.",
  ui_story_5048_50480701_7_dialog_content = "Ese dueño de restaurante, Ernesto, ya ha sido curado.",
  ui_story_5048_50480701_8_dialog_content = "¿Por qué seguimos buscando hierbas para él?",
  ui_story_5048_50480701_9_dialog_content = "Aunque su vida ya no corre un gran peligro, su salud debe haber sido gravemente afectada.",
  ui_story_5048_50480701_10_dialog_content = "En este momento, solo una selección muy específica de hierbas puede nutrir rápidamente su cuerpo y mente para compensar la deficiencia que queda en su constitución.",
  ui_story_5048_50480701_11_dialog_content = "El Sr. Ernest y yo compartimos una profunda apreciación de las fortalezas del otro. Tal amistad es verdaderamente rara, y valoro mucho este vínculo.",
  ui_story_5048_50480701_12_dialog_content = "Entonces, por supuesto, debería mostrarle mi gratitud de inmediato y dejar que experimente un tónico tradicional de Longzhou.",
  ui_story_5048_50480701_13_dialog_content = "Esto también podría considerarse una historia muy contada en la historia del intercambio culinario entre Astra y Longzhou.",
  ui_story_5048_50480701_14_dialog_content = "Pero, ¿realmente se pueden encontrar las hierbas de Longzhou en este lugar?",
  ui_story_5048_50480701_15_dialog_content = "Ya lo he confirmado con los lugareños.",
  ui_story_5048_50480701_16_dialog_content = "Este lugar no tiene nuestras hierbas, pero hay un tipo útil conocido como la baya de lobo roja, que siempre han considerado simplemente como una mala hierba.",
  ui_story_5048_50480701_17_dialog_content = "Llovió bastante fuerte hace unos días, así que ahora que el cielo está despejado, debería ser el momento perfecto para que florezca el bayas de goji rojas.",
  ui_story_5048_50480701_18_dialog_content = "¡Fruta roja adelante!",
  ui_story_5048_50480701_19_dialog_content = "¡Delicioso! ¡Tan delicioso!",
  ui_story_5048_50480701_20_dialog_content = "Ya que ustedes dos parecen ser tan hábiles buscando comida en la naturaleza, pueden dejar de pedirme melones y dátiles todos los días, a partir de ahora.",
  ui_story_5048_50480701_21_dialog_content = "Espera, la fruta que Squawk y Jabber están comiendo...",
  ui_story_5048_50480701_22_dialog_content = "¡Es baya de goji roja!",
  ui_story_5048_50480701_23_dialog_content = "¡Lo encontramos! ¡En realidad lo encontramos!",
  ui_story_5048_50480701_24_dialog_content = "Oh, ¿así que esta pequeña fruta roja es una medicina herbal?",
  ui_story_5048_50480701_25_dialog_content = "Tianxian, no comas tantos crudos así, aumentan rápidamente tu fuego interno y causan diarrea.",
  ui_story_5048_50480701_26_dialog_content = "Señorita Jiu, realmente deberías haber dicho algo antes...",
  ui_story_5048_50480701_27_dialog_content = "Graznido, Farfullar, ¿escucharon eso? Coman demasiado y solo tendrán a ustedes mismos a quien culpar por las consecuencias...",
  ui_story_5048_50480701_28_dialog_content = "Basta de jugar, recuerda recoger todo lo que puedas y llenar tus canastas.",
  ui_story_5048_50480701_29_dialog_content = "¡Sí, Princesa!",
  ui_story_5048_50480701_30_dialog_content = "Por supuesto.",
  ui_story_5048_50480701_31_dialog_content = "Hermanas, me pregunto qué estarán haciendo ustedes dos ahora mismo...",
  ui_story_5048_50480701_32_dialog_content = "Todo está bien aquí y los asuntos avanzan de manera ordenada.",
  ui_story_5048_50480701_33_dialog_content = "Y también tengo la sensación...",
  ui_story_5048_50480701_34_dialog_content = "¡Que tal vez en el futuro, experimentaré aún más eventos interesantes en Astra!",
  ui_story_5048_50480701_35_dialog_content = "También espero encontrar un pianista dispuesto a tocar una pieza junto a mi pipa.",
  ui_story_5048_50480701_36_dialog_content = "Solo pensando en esto...",
  ui_story_5048_50480701_37_dialog_content = "¡Estoy emocionado por ver qué traerá el día de mañana!"
}
return config
